-- Synchronise the invoice counter AFTER importing demonstration sales.
SELECT CAST(SUBSTRING(invoice_no, 5, 4) AS UNSIGNED),
       MAX(CAST(SUBSTRING(invoice_no, 9) AS UNSIGNED))
FROM sales WHERE invoice_no LIKE 'INV-%'
GROUP BY CAST(SUBSTRING(invoice_no, 5, 4) AS UNSIGNED)
ON DUPLICATE KEY UPDATE next_no = GREATEST(invoice_counters.next_no, VALUES(next_no));
